class Surah {
  final int id;
  final String nameArabic;
  final String nameSimple;
  final String nameUyghur;
  final String revelationPlace; // 'makkah' or 'madinah'
  final int versesCount;
  final bool bismillahPre;

  const Surah({
    required this.id,
    required this.nameArabic,
    required this.nameSimple,
    required this.nameUyghur,
    required this.revelationPlace,
    required this.versesCount,
    required this.bismillahPre,
  });

  String get revelationPlaceUyghur =>
      revelationPlace.toLowerCase() == 'madinah' ? 'مەدىنە' : 'مەككە';

  factory Surah.fromQuranComJson(Map<String, dynamic> json) {
    final id = json['id'] as int;
    final fallback = allSurahs.firstWhere(
      (s) => s.id == id,
      orElse: () => Surah(
        id: id,
        nameArabic: json['name_arabic']?.toString() ?? '',
        nameSimple: json['name_simple']?.toString() ?? '',
        nameUyghur: json['name_simple']?.toString() ?? '',
        revelationPlace: json['revelation_place']?.toString() ?? 'makkah',
        versesCount: (json['verses_count'] as num?)?.toInt() ?? 0,
        bismillahPre: json['bismillah_pre'] as bool? ?? (id != 1 && id != 9),
      ),
    );

    return Surah(
      id: id,
      nameArabic: json['name_arabic']?.toString() ?? fallback.nameArabic,
      nameSimple: json['name_simple']?.toString() ?? fallback.nameSimple,
      nameUyghur: fallback.nameUyghur,
      revelationPlace:
          json['revelation_place']?.toString() ?? fallback.revelationPlace,
      versesCount: (json['verses_count'] as num?)?.toInt() ?? fallback.versesCount,
      bismillahPre: json['bismillah_pre'] as bool? ?? fallback.bismillahPre,
    );
  }

